const createStaff = (staff) => request("", { method: "POST", body: JSON.stringify(staff) });
const updateStaff = (id, staff) => request(`/${id}`, { method: "PATCH", body: JSON.stringify(staff) });
const deactivateStaff = (id) => request(`/${id}`, { method: "DELETE" });

