// explicit bootstrap option; normal startup leaves database-owned periods
// unchanged.

const { pool } = require("../config/database");

const PERIOD_LENGTH_DAYS = 14;
const PERIODS_TO_GENERATE = 260; // ~10 years of fortnightly periods
const ANCHOR_START = new Date("2026-01-01T00:00:00Z");

const SELECT_COLUMNS = `
  id,
  to_char(start_date, 'YYYY-MM-DD') AS "startDate",
  to_char(end_date, 'YYYY-MM-DD') AS "endDate"
`;

function formatDate(date) {
  return date.toISOString().slice(0, 10);
}

function buildPeriodDates(index) {
  const start = new Date(ANCHOR_START);
  start.setUTCDate(start.getUTCDate() + index * PERIOD_LENGTH_DAYS);

  const end = new Date(start);
  end.setUTCDate(end.getUTCDate() + PERIOD_LENGTH_DAYS - 1);

  return { startDate: formatDate(start), endDate: formatDate(end) };
}

// Makes sure a year of fortnightly pay periods exists in the database.
// Safe to call every time the server starts â€” start_date has a unique
// constraint, so periods that already exist are left untouched.
async function ensurePayPeriodsSeeded({ periodCount = PERIODS_TO_GENERATE } = {}) {
  if (!Number.isInteger(periodCount) || periodCount < 1) {
    throw new TypeError("periodCount must be a positive integer");
  }

  const client = await pool.connect();
  let createdCount = 0;
  try {
    await client.query("BEGIN");
    await client.query("SELECT pg_advisory_xact_lock(hashtext('pay_period_generation'))");
    for (let index = 0; index < periodCount; index += 1) {
      const { startDate, endDate } = buildPeriodDates(index);
      const result = await client.query(
        `INSERT INTO pay_period (start_date, end_date)
         SELECT $1, $2
         WHERE NOT EXISTS (
           SELECT 1 FROM pay_period WHERE start_date <= $2 AND end_date >= $1
         )
         ON CONFLICT (start_date) DO NOTHING
         RETURNING id`,
        [startDate, endDate]
      );
      createdCount += result.rowCount;
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
  return {
    ok: true,
    createdCount,
    message: `Pay-period generation completed (${createdCount} created, ${periodCount - createdCount} existing or overlapping)`,
  };
}

// Marks which period is "active" (covers today) so the frontend can
// default its dropdown without re-implementing this date logic itself.
async function listPayPeriods() {
  const { rows } = await pool.query(`SELECT ${SELECT_COLUMNS} FROM pay_period ORDER BY start_date, id`);
  const today = formatDate(new Date());
  return rows.map((period) => ({
    ...period,
    isActive: period.startDate <= today && today <= period.endDate,
  }));
}

async function getPayPeriod(payPeriodId) {
  const { rows } = await pool.query(`SELECT ${SELECT_COLUMNS} FROM pay_period WHERE id = $1`, [payPeriodId]);
  return rows[0] || null;
}

// The period whose date range contains today â€” what "Import Now" and the
// nightly scheduler default to when no period is explicitly selected.
async function getActivePayPeriod() {
  const today = formatDate(new Date());
  const { rows } = await pool.query(
    `SELECT ${SELECT_COLUMNS}
     FROM pay_period
     WHERE start_date <= $1 AND end_date >= $1
     ORDER BY start_date DESC, end_date ASC, id ASC
     LIMIT 1`,
    [today]
  );
  if (rows[0]) return rows[0];

  // Today falls outside every generated period â€” fall back to the earliest
  // period rather than returning nothing.
  const fallback = await pool.query(`SELECT ${SELECT_COLUMNS} FROM pay_period ORDER BY start_date, id LIMIT 1`);
  return fallback.rows[0] || null;
}

module.exports = { ensurePayPeriodsSeeded, listPayPeriods, getPayPeriod, getActivePayPeriod };
// UC-001: The core roster-sync logic.
// Matches roster rows to staff and saves each one as its own shift-level
// timesheet row (not summed), so UC-002 can later check per-date rules
// like overlapping shifts. Unmatched/invalid rows are flagged and excluded
// from totals instead of corrupting them.

const { pool } = require("../config/database");
const { fetchRosterRows } = require("../adapters/googleSheetsAdapter");
const payPeriodService = require("./payPeriodService");
const auditService = require("./auditService");
const { calculateHours } = require("../utils/hoursCalculator");

// Match a roster row to an active staff record. Staff ID is checked first
// because it's the reliable identifier; name is only a fallback for when
// the ID is missing or wrong, since names can have typos or duplicates.
// If a record exists but is inactive, that's reported separately from a
// truly unknown staff member, since the fix for each is different.
async function findMatchingStaff(rosterRow) {
  const byId = await pool.query(
    `SELECT id, external_ref AS "staffId", full_name AS "fullName", status FROM staff WHERE external_ref = $1`,
    [rosterRow["Staff ID"]]
  );
  const idMatch = byId.rows[0];
  if (idMatch && idMatch.status === "active") return { ...idMatch, matchMethod: "id" };

  const byName = await pool.query(
    `SELECT id, external_ref AS "staffId", full_name AS "fullName", status FROM staff WHERE lower(full_name) = lower($1)`,
    [rosterRow["Staff Name"]]
  );
  const nameMatch = byName.rows[0];
  if (nameMatch && nameMatch.status === "active") return { ...nameMatch, matchMethod: "name" };

  const inactiveMatch = (idMatch && idMatch.status === "inactive") || (nameMatch && nameMatch.status === "inactive");
  if (inactiveMatch) return { inactive: true, fullName: (idMatch || nameMatch).fullName };

  return null;
}

// Runs a full roster sync: read rows -> match -> total hours -> save draft.
// payPeriodId defaults to whichever period covers today, so "Import Now"
// and the automatic scheduler both work without the caller picking one.
async function runRosterSync(payPeriodId, actor = "manual") {
  if (!payPeriodId) {
    const activePeriod = await payPeriodService.getActivePayPeriod();
    if (!activePeriod) {
      return {
        success: false,
        error: "ACTIVE_PAY_PERIOD_NOT_FOUND",
        message: "No active pay period is available",
      };
    }
    payPeriodId = activePeriod.id;
  }

  // The use case says the sync reads roster rows "for the active pay
  // period" â€” we need the period's date range to actually enforce that,
  // otherwise syncing any period would pull every row in the sheet
  // regardless of date.
  const payPeriod = await payPeriodService.getPayPeriod(payPeriodId);
  if (!payPeriod) {
    return {
      success: false,
      error: "PAY_PERIOD_NOT_FOUND",
      message: "The selected pay period does not exist",
    };
  }

  const previousDraft = await getLastSyncResult(payPeriodId);
  let rosterRows;

  try {
    rosterRows = await fetchRosterRows();
  } catch (err) {
    console.error("[rosterSyncService] Could not read the roster sheet:", err.message);
    await auditService.logAction({
      entityType: "pay_period",
      entityId: payPeriodId,
      action: "roster_sync_failed",
      actor,
      detail: { reason: "unreachable" },
    });
    return {
      success: false,
      error: "ROSTER_SOURCE_UNREACHABLE",
      message: "Google Sheet could not be read; previous draft retained",
      previousDraft,
    };
  }

  if (!rosterRows || rosterRows.length === 0) {
    console.error("[rosterSyncService] The roster sheet had no rows.");
    await auditService.logAction({
      entityType: "pay_period",
      entityId: payPeriodId,
      action: "roster_sync_failed",
      actor,
      detail: { reason: "empty" },
    });
    return {
      success: false,
      error: "ROSTER_SOURCE_EMPTY",
      message: "Google Sheet was empty; previous draft retained",
      previousDraft,
    };
  }

  const resolvedRows = await pool.query(
    `SELECT to_char(shift_date, 'YYYY-MM-DD') AS shift_date, source_key
     FROM timesheet
     WHERE pay_period_id = $1 AND resolved_manually = true AND source_key IS NOT NULL`,
    [payPeriodId]
  );
  const resolvedSourceKeys = new Set(
    resolvedRows.rows.map((row) => `${row.shift_date}|${row.source_key}`)
  );
  const matchedShifts = [];
  const unmatchedRows = [];
  const invalidTimeRows = [];
  const outOfPeriodRows = [];

  for (const row of rosterRows) {
    // Skip rows outside the target period's date range so syncing one
    // period never pulls in another period's shifts. Dates are plain
    // YYYY-MM-DD strings, so a direct string comparison sorts correctly.
    if (row["Date"] < payPeriod.startDate || row["Date"] > payPeriod.endDate) {
      outOfPeriodRows.push({ rosterRawName: row["Staff Name"], date: row["Date"] });
      continue;
    }

    const matchResult = await findMatchingStaff(row);
    const hoursForRow = calculateHours(row["Clock In"], row["Clock Out"]);

    if (Number.isNaN(hoursForRow)) {
      if (resolvedSourceKeys.has(`${row["Date"]}|${row["Staff Name"]}`)) continue;
      const label = matchResult && !matchResult.inactive ? matchResult.fullName : row["Staff Name"];
      invalidTimeRows.push({
        staffDbId: matchResult && !matchResult.inactive ? matchResult.id : null,
        rosterRawName: `${label} (missing clock-in/out)`,
        sourceKey: row["Staff Name"],
        date: row["Date"],
        clockIn: row["Clock In"] || null,
        clockOut: row["Clock Out"] || null,
      });
      continue;
    }

    if (!matchResult) {
      if (resolvedSourceKeys.has(`${row["Date"]}|${row["Staff Name"]}`)) continue;
      unmatchedRows.push({ rosterRawName: row["Staff Name"], sourceKey: row["Staff Name"], date: row["Date"], hours: hoursForRow });
      continue;
    }

    if (matchResult.inactive) {
      if (resolvedSourceKeys.has(`${row["Date"]}|${row["Staff Name"]}`)) continue;
      unmatchedRows.push({ rosterRawName: `${matchResult.fullName} (inactive staff)`, sourceKey: row["Staff Name"], date: row["Date"], hours: hoursForRow });
      continue;
    }

    matchedShifts.push({
      staffDbId: matchResult.id,
      date: row["Date"],
      hours: hoursForRow,
      matchMethod: matchResult.matchMethod,
      clockIn: row["Clock In"],
      clockOut: row["Clock Out"],
    });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    // Replace the draft for this period. Rows already frozen by UC-002
    // validation are left alone, so a re-sync can never overwrite a
    // validated snapshot.
    await client.query("DELETE FROM timesheet WHERE pay_period_id = $1 AND is_frozen = false AND resolved_manually = false", [payPeriodId]);

    for (const shift of matchedShifts) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, shift_date, total_hours, match_status, match_method, clock_in, clock_out)
         VALUES ($1, $2, $3, $4, 'matched', $5, $6, $7)`,
        [payPeriodId, shift.staffDbId, shift.date, shift.hours, shift.matchMethod, shift.clockIn, shift.clockOut]
      );
    }

    for (const entry of unmatchedRows) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, roster_raw_name, shift_date, total_hours, match_status, source_key)
         VALUES ($1, NULL, $2, $3, $4, 'unmatched', $5)`,
        [payPeriodId, entry.rosterRawName, entry.date, entry.hours, entry.sourceKey]
      );
    }

    for (const entry of invalidTimeRows) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, roster_raw_name, shift_date, total_hours, match_status, source_key, clock_in, clock_out)
         VALUES ($1, $2, $3, $4, 0, 'invalid_time', $5, $6, $7)`,
        [payPeriodId, entry.staffDbId, entry.rosterRawName, entry.date, entry.sourceKey, entry.clockIn, entry.clockOut]
      );
    }

    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }

  const result = await getLastSyncResult(payPeriodId);
  await auditService.logAction({
    entityType: "pay_period",
    entityId: payPeriodId,
    action: "roster_synced",
    actor,
    detail: {
      staffSynced: result.staffSynced,
      totalHours: result.totalHours,
      unmatchedCount: result.unmatchedCount,
      invalidTimeCount: result.invalidTimeCount,
      outOfPeriodCount: outOfPeriodRows.length,
    },
  });
  return result;
}

