// UC-001: Handles the HTTP requests for roster sync and passes the work
// along to rosterSyncService, then sends back a JSON response.

const rosterSyncService = require("../services/rosterSyncService");

// POST /api/roster/sync â€” "Import Now" button
async function importNow(req, res, next) {
  try {
    const { payPeriodId, simulateFailure } = req.body;

    if (simulateFailure) {
      // Demo-only path: lets accounting staff show alt flow 1b (sheet
      // unreachable) live without actually editing .env mid-demo.
      const previousDraft = await rosterSyncService.getLastSyncResult(payPeriodId);
      return res.status(424).json({
        success: false,
        error: "ROSTER_SOURCE_UNREACHABLE",
        message: "Simulated failure for demo purposes; previous draft retained",
        previousDraft,
      });
    }

    const result = await rosterSyncService.runRosterSync(payPeriodId, "manual");

    if (!result.success) {
      // 424 = "the thing we depend on (the Google Sheet) failed"
      return res.status(424).json(result);
    }

    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

// GET /api/roster/sync/summary â€” shows the latest sync result on page load
async function getSyncSummary(req, res, next) {
  try {
    const result = await rosterSyncService.getLastSyncResult(req.query.payPeriodId);
    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

// GET /api/roster/sync/history â€” recent sync events (manual + scheduled) for this period
async function getSyncHistory(req, res, next) {
  try {
    const history = await rosterSyncService.getSyncHistory(req.query.payPeriodId);
    res.status(200).json({ history });
  } catch (err) {
    next(err);
  }
}

async function resolveException(req, res, next) {
  try {
    const result = await rosterSyncService.resolveException(req.params.timesheetRowId, req.body);
    if (!result.success) {
      const status = result.error === "TIMESHEET_ROW_NOT_FOUND" ? 404 : result.error === "TIMESHEET_ROW_FROZEN" ? 409 : 400;
      return res.status(status).json(result);
    }
    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

async function getResolvedExceptions(req, res, next) {
  try {
    const resolvedExceptions = await rosterSyncService.getResolvedExceptions(req.query.payPeriodId);
    res.status(200).json({ resolvedExceptions });
  } catch (err) {
    next(err);
  }
}

async function undoException(req, res, next) {
  try {
    const result = await rosterSyncService.undoException(req.params.timesheetRowId);
    if (!result.success) {
      const status = result.error === "TIMESHEET_ROW_NOT_FOUND" ? 404 : result.error === "TIMESHEET_ROW_FROZEN" ? 409 : 400;
      return res.status(status).json(result);
    }
    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

async function resetPeriodResolutions(req, res, next) {
  try {
    const result = await rosterSyncService.resetPeriodResolutions(req.body.payPeriodId);
    if (!result.success) return res.status(424).json(result);
    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

module.exports = { importNow, getSyncSummary, getSyncHistory, resolveException, getResolvedExceptions, undoException, resetPeriodResolutions };
// UC-001: Routes for roster sync.

const express = require("express");
const rosterController = require("../controllers/rosterController");

const router = express.Router();

router.post("/sync", rosterController.importNow);
router.get("/sync/summary", rosterController.getSyncSummary);
router.get("/sync/history", rosterController.getSyncHistory);
router.get("/exceptions/resolved", rosterController.getResolvedExceptions);
router.post("/exceptions/:timesheetRowId/resolve", rosterController.resolveException);
router.post("/exceptions/:timesheetRowId/undo", rosterController.undoException);
router.post("/exceptions/reset", rosterController.resetPeriodResolutions);

module.exports = router;
const { parse } = require("csv-parse/sync");

// Fetches the published roster CSV and returns an array of row objects.
// Each row looks like: { "Staff ID": "S001", "Staff Name": "Andrea Chua", "Date": "2026-07-01", "Clock In": "08:00", "Clock Out": "17:00" }
async function fetchRosterRows() {
  const url = process.env.ROSTER_SHEET_CSV_URL;

  if (!url) {
    throw new Error("ROSTER_SHEET_CSV_URL is not set in .env");
  }

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Failed to fetch roster sheet: ${response.status} ${response.statusText}`);
  }

  const csvText = await response.text();

  const rows = parse(csvText, {
    columns: true,       // use first row as headers
    skip_empty_lines: true,
    trim: true,
  });

  return rows;
}

module.exports = { fetchRosterRows };
// UC-001: API wrapper functions for roster sync, built on top of the
// shared apiGet/apiPost helpers in api/client.js.

import { apiGet, apiPost } from "./client";

function fetchPayPeriods() {
  return apiGet("/api/pay-periods");
}

function fetchSyncSummary(payPeriodId) {
  return apiGet(`/api/roster/sync/summary?payPeriodId=${payPeriodId}`);
}

function fetchSyncHistory(payPeriodId) {
  return apiGet(`/api/roster/sync/history?payPeriodId=${payPeriodId}`);
}

function triggerImportNow(payPeriodId) {
  return apiPost("/api/roster/sync", { payPeriodId }, { allowStatuses: [424] });
}

function simulateSheetDown(payPeriodId) {
  return apiPost("/api/roster/sync", { payPeriodId, simulateFailure: true }, { allowStatuses: [424] });
}

function resolveException(timesheetRowId, resolution) {
  return apiPost(`/api/roster/exceptions/${timesheetRowId}/resolve`, resolution);
}

function fetchResolvedExceptions(payPeriodId) {
  return apiGet(`/api/roster/exceptions/resolved?payPeriodId=${payPeriodId}`);
}

function undoException(timesheetRowId) {
  return apiPost(`/api/roster/exceptions/${timesheetRowId}/undo`, {});
}

function resetPeriodResolutions(payPeriodId) {
  return apiPost("/api/roster/exceptions/reset", { payPeriodId });
}

export { fetchPayPeriods, fetchSyncSummary, fetchSyncHistory, triggerImportNow, simulateSheetDown, resolveException, fetchResolvedExceptions, undoException, resetPeriodResolutions };
